"use client";

import { useEffect, useState } from "react";
import { LayoutDashboard, ClipboardList, Users, FileText, ReceiptText, WalletCards, Settings, Bell, Search, Plus, CalendarDays, MapPin, Phone, CheckCircle2, Clock3, MoreHorizontal, Menu, X, Eye, Send, Download, Filter, BadgeCheck, TrendingUp } from "lucide-react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { callRpc, createEmployeeAccount, getSession, getUserId, insertPublicRecord, insertRecord, selectRecords, signIn, signOut, signUp, updateRecord } from "@/lib/supabase";

const nav = [["نظرة عامة", LayoutDashboard], ["طلبات عروض السعر", FileText], ["إدارة المشاريع", CalendarDays], ["الرقابة والربحية", TrendingUp], ["خدمة العملاء والتسويق", Phone], ["مهامي", CheckCircle2], ["طلبات الخدمة", ClipboardList], ["العملاء", Users], ["عروض الأسعار", FileText], ["العقود", ReceiptText], ["الفواتير والتحصيل", WalletCards], ["التقارير والإغلاق", BadgeCheck], ["الموظفون والصلاحيات", Settings]] as const;
type Role = "السوبر أدمن" | "المدير العام" | "مدير المشاريع" | "خدمة العملاء" | "التسويق" | "المبيعات" | "مشرف العمليات" | "المحاسب";
const permissions: Record<Role, { sections: string[]; create: string[]; export: boolean }> = {
  "السوبر أدمن": { sections: nav.map(([n]) => n), create: nav.map(([n]) => n), export: true },
  "المدير العام": { sections: nav.filter(([n]) => n !== "الموظفون والصلاحيات").map(([n]) => n), create: ["طلبات الخدمة", "العملاء", "عروض الأسعار", "العقود", "الفواتير والتحصيل"], export: true },
  "مدير المشاريع": { sections: ["نظرة عامة", "إدارة المشاريع", "الرقابة والربحية", "مهامي", "طلبات الخدمة", "العملاء"], create: ["طلبات الخدمة"], export: false },
  "خدمة العملاء": { sections: ["نظرة عامة", "خدمة العملاء والتسويق", "مهامي", "العملاء", "طلبات الخدمة"], create: [], export: false },
  "التسويق": { sections: ["نظرة عامة", "طلبات عروض السعر", "خدمة العملاء والتسويق", "مهامي", "العملاء"], create: [], export: false },
  "المبيعات": { sections: ["نظرة عامة", "طلبات عروض السعر", "مهامي", "طلبات الخدمة", "العملاء", "عروض الأسعار"], create: ["طلبات الخدمة", "العملاء", "عروض الأسعار"], export: false },
  "مشرف العمليات": { sections: ["نظرة عامة", "إدارة المشاريع", "الرقابة والربحية", "مهامي", "طلبات الخدمة", "العملاء"], create: ["طلبات الخدمة"], export: false },
  "المحاسب": { sections: ["نظرة عامة", "الرقابة والربحية", "مهامي", "العملاء", "العقود", "الفواتير والتحصيل", "التقارير والإغلاق"], create: ["الفواتير والتحصيل"], export: true },
};
const info: Record<string, { note: string; action: string; columns: string[] }> = {
  "طلبات الخدمة": { note: "متابعة الطلب من الاستلام والمعاينة حتى التنفيذ", action: "طلب جديد", columns: ["رقم الطلب", "العميل والخدمة", "الموقع", "الحالة", "الإجراء"] },
  "العملاء": { note: "ملفات العملاء وسجل الطلبات والتواصل", action: "إضافة عميل", columns: ["العميل", "رقم الجوال", "آخر خدمة", "الرصيد", "الإجراء"] },
  "عروض الأسعار": { note: "إعداد العروض وإرسالها واعتمادها إلكترونيًا", action: "عرض سعر جديد", columns: ["رقم العرض", "العميل", "القيمة", "الحالة", "الإجراء"] },
  "العقود": { note: "العقود النشطة والتجديدات والتوقيع", action: "عقد جديد", columns: ["رقم العقد", "العميل", "المدة", "القيمة", "الحالة"] },
  "الفواتير والتحصيل": { note: "الفواتير المستحقة والمدفوعات والإيصالات", action: "فاتورة جديدة", columns: ["رقم الفاتورة", "العميل", "الاستحقاق", "القيمة", "الحالة"] },
};

export default function Home() {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState("نظرة عامة");
  const [mode, setMode] = useState<"admin" | "customer">("admin");
  const [role, setRole] = useState<Role>("السوبر أدمن");
  const [notice, setNotice] = useState("");
  const [formType, setFormType] = useState<string | null>(null);
  const [loginOpen, setLoginOpen] = useState(false);
  // Keep the first server and browser render identical; restore the saved session after mount.
  const [connected, setConnected] = useState(false);
  const [sessionChecked, setSessionChecked] = useState(false);
  const [accountKind, setAccountKind] = useState<"loading" | "staff" | "customer">("loading");
  const [profileName, setProfileName] = useState("المستخدم");
  const [assignedSections, setAssignedSections] = useState<string[]>([]);
  const [customerRefresh, setCustomerRefresh] = useState(0);
  const basePermit = permissions[role];
  const permit = role === "السوبر أدمن" || !assignedSections.length ? basePermit : { ...basePermit, sections: ["نظرة عامة", "مهامي", ...assignedSections.filter(x => !["نظرة عامة", "مهامي", "الموظفون والصلاحيات"].includes(x))] };
  useEffect(() => {
    setConnected(Boolean(getSession()));
    setSessionChecked(true);
  }, []);
  useEffect(() => {
    if (!connected) return;
    const id = getUserId();
    if (!id) return;
    selectRecords("pr_profiles", `id=eq.${id}&select=role,full_name,permissions,is_active`).then(rows => {
      const dbRole = String(rows[0]?.role || "");
      if (rows[0]?.is_active === false) { signOut(); setConnected(false); return; }
      setProfileName(String(rows[0]?.full_name || "المستخدم"));
      setAssignedSections(Array.isArray(rows[0]?.permissions) ? rows[0].permissions as string[] : []);
      const roleMap: Record<string, Role> = { super_admin: "السوبر أدمن", admin: "المدير العام", manager: "مدير المشاريع", project_manager: "مدير المشاريع", customer_service: "خدمة العملاء", marketing: "التسويق", sales: "المبيعات", operations: "مشرف العمليات", accountant: "المحاسب" };
      if (roleMap[dbRole]) { setRole(roleMap[dbRole]); setAccountKind("staff"); }
      else setAccountKind("customer");
    }).catch(() => setAccountKind("customer"));
  }, [connected]);
  const notify = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(""), 2200); };
  if (!sessionChecked) return <div className="authLoading" dir="rtl"><img src="/brand/logo.png" alt="Purity Ritual"/><span>جاري تحميل النظام...</span></div>;
  if (!connected) return <PublicHome onConnected={() => { setConnected(true); setAccountKind("loading"); }}/>;
  if (accountKind === "loading") return <div className="authLoading" dir="rtl"><img src="/brand/logo.png" alt="Purity Ritual"/><span>جاري تجهيز حسابك...</span></div>;
  if (accountKind === "customer") return <div className="customerOnly" dir="rtl"><header><img src="/brand/logo.png" alt="Purity Ritual"/><strong>بوابة العميل</strong><button onClick={() => { signOut(); setConnected(false); }}>تسجيل الخروج</button></header><Customer key={customerRefresh} notify={notify} onCreate={() => setFormType("طلب خدمة")}/>{notice && <div className="toast"><BadgeCheck/>{notice}</div>}<CreateForm type={formType} onClose={() => setFormType(null)} onNeedLogin={() => undefined} onSaved={(label) => { setFormType(null); setCustomerRefresh(v=>v+1); notify(`تم إرسال ${label} بنجاح`); }}/></div>;
  return <div className="shell" dir="rtl">
    <aside className={open ? "side open" : "side"}>
      <div className="brand"><img src="/brand/logo.png" alt="شعار Purity Ritual"/><div className="brandname"><strong>Purity</strong><span>Ritual</span></div><button onClick={() => setOpen(false)} aria-label="إغلاق القائمة"><X/></button></div>
      <div className="workspace"><span>مساحة الإدارة</span><strong>Purity Ritual</strong><small>{role}</small></div>
      <nav>{nav.filter(([name]) => permit.sections.includes(name)).map(([name, Icon]) => <button key={name} className={active === name ? "active" : ""} onClick={() => { setActive(name); setMode("admin"); setOpen(false); }}><Icon/><span>{name}</span></button>)}</nav>
      <div className="sidefoot"><div className="profile"><i>{profileName.slice(0,1)}</i><div><strong>{profileName}</strong><small>{role}</small></div><MoreHorizontal/></div></div>
    </aside>
    <main><header className="top"><button className="menub" onClick={() => setOpen(true)} aria-label="فتح القائمة"><Menu/></button><div className="search"><Search/><input placeholder="ابحث عن عميل، طلب، أو فاتورة..." aria-label="البحث"/></div><div className="topactions"><button className="bell" aria-label="الإشعارات"><Bell/><i/></button><button className="accountButton" onClick={() => setLoginOpen(true)}>{role}</button></div></header>
      {mode === "customer" ? <Customer notify={notify} onCreate={() => setFormType("طلب خدمة")}/> : active === "نظرة عامة" ? <Dashboard name={profileName} notify={notify} canCreate={permit.create.includes("طلبات الخدمة")} onCreate={() => setFormType("طلب خدمة")}/> : active === "طلبات عروض السعر" ? <LeadBoard notify={notify}/> : active === "إدارة المشاريع" ? <WorkflowBoard notify={notify}/> : active === "الرقابة والربحية" ? <ProjectControlBoard notify={notify}/> : active === "خدمة العملاء والتسويق" ? <FollowupBoard notify={notify}/> : active === "عروض الأسعار" ? <QuotationBoard notify={notify}/> : active === "الفواتير والتحصيل" ? <InvoiceBoard notify={notify}/> : active === "التقارير والإغلاق" ? <ReportsBoard notify={notify}/> : active === "مهامي" ? <EmployeeTasks notify={notify}/> : active === "الموظفون والصلاحيات" ? <EmployeesPermissions notify={notify}/> : <Management section={active} connected={connected} notify={notify} canCreate={permit.create.includes(active)} canExport={permit.export} onCreate={() => setFormType(info[active].action)} onRecordPayment={() => setFormType("تسجيل دفعة")}/>} 
      {notice && <div className="toast"><BadgeCheck/>{notice}</div>}
      <DatabaseLogin open={loginOpen} connected={connected} onClose={() => setLoginOpen(false)} onConnected={() => { setConnected(true); setLoginOpen(false); notify("تم تسجيل الدخول"); }} onDisconnected={() => { setConnected(false); setLoginOpen(false); notify("تم تسجيل الخروج"); }}/>
      <CreateForm type={formType} onClose={() => setFormType(null)} onNeedLogin={() => setLoginOpen(true)} onSaved={(label) => { setFormType(null); notify(`تم حفظ ${label} بنجاح`); }}/>
    </main>
  </div>;
}

function Dashboard({ name, notify, canCreate, onCreate }: { name:string; notify:(m:string)=>void; canCreate:boolean; onCreate:()=>void }) {
  const [data,setData]=useState<{requests:Record<string,unknown>[];quotes:Record<string,unknown>[];payments:Record<string,unknown>[]}>({requests:[],quotes:[],payments:[]});
  const [loading,setLoading]=useState(true);
  useEffect(()=>{void (async()=>{const results=await Promise.allSettled([selectRecords("pr_service_requests","select=*&order=created_at.desc"),selectRecords("pr_quotations","select=*&order=created_at.desc"),selectRecords("pr_payments","select=*&order=created_at.desc")]);setData({requests:results[0].status==="fulfilled"?results[0].value:[],quotes:results[1].status==="fulfilled"?results[1].value:[],payments:results[2].status==="fulfilled"?results[2].value:[]});setLoading(false);})();},[]);
  const currentMonth=new Date().toISOString().slice(0,7);
  const newRequests=data.requests.filter(r=>r.status==="new");
  const scheduled=data.requests.filter(r=>["scheduled","in_progress"].includes(String(r.status)));
  const waitingQuotes=data.quotes.filter(q=>q.status==="sent");
  const monthPayments=data.payments.filter(p=>String(p.paid_at||p.created_at||"").startsWith(currentMonth));
  const paid=monthPayments.reduce((sum,p)=>sum+Number(p.amount||0),0);
  const recentRows=data.requests.slice(0,6).map(r=>[String(r.request_no||"—"),`${r.customer_name||"عميل"} — ${r.service_type||"خدمة"}`,String(r.address||r.city||"—"),workflowLabels[String(r.status)]||String(r.status||"—"),"عرض"]);
  return <div className="page"><section className="pagehead"><div><p>{new Intl.DateTimeFormat("ar-SA",{dateStyle:"full"}).format(new Date())}</p><h1>مرحبًا، {name}</h1><span>هذه البيانات الفعلية المسجلة في النظام.</span></div>{canCreate&&<button className="primary" onClick={onCreate}><Plus/>طلب خدمة جديد</button>}</section>
    <section className="stats"><Stat label="طلبات جديدة" value={String(newRequests.length)} note="من قاعدة البيانات" icon={<ClipboardList/>}/><Stat label="خدمات مجدولة أو جارية" value={String(scheduled.length)} note="تحتاج متابعة" icon={<CalendarDays/>}/><Stat label="عروض بانتظار العميل" value={String(waitingQuotes.length)} note="بانتظار الاعتماد" icon={<FileText/>}/><Stat label="تحصيل هذا الشهر" value={paid.toLocaleString("ar-SA")} note="ر.س محصلة فعليًا" icon={<WalletCards/>}/></section>
    <section className="panel"><h2>أحدث طلبات الخدمة</h2>{loading?<div className="emptyState">جاري تحميل البيانات...</div>:recentRows.length?<DataTable columns={["الطلب","العميل والخدمة","الموقع","الحالة","الإجراء"]} rows={recentRows} notify={notify}/>:<div className="emptyState">لا توجد طلبات حقيقية حتى الآن</div>}</section>
  </div>;
}

const workflowLabels: Record<string,string> = { new:"طلب جديد",reviewing:"قيد المراجعة",quoted:"بانتظار اعتماد العرض",approved:"عرض معتمد",scheduled:"تم إسناد الفريق",in_progress:"قيد التنفيذ",completed:"مكتملة",cancelled:"ملغاة" };

function WorkflowBoard({ notify }: { notify: (m: string) => void }) {
  const [items,setItems] = useState<Record<string,unknown>[]>([]);
  const [employees,setEmployees] = useState<Record<string,unknown>[]>([]);
  const [quotes,setQuotes] = useState<Record<string,unknown>[]>([]);
  const [quoteRequest,setQuoteRequest] = useState<Record<string,unknown>|null>(null);
  const [amounts,setAmounts] = useState<Record<string,string>>({});
  const [assignees,setAssignees] = useState<Record<string,string>>({});
  const [loading,setLoading] = useState(true);
  const load = async () => {
    setLoading(true);
    try {
      const [requestsData,staffData,quotesData] = await Promise.all([
        selectRecords("pr_service_requests","select=*&order=created_at.desc&limit=100"),
        selectRecords("pr_profiles","role=in.(manager,sales,operations)&is_active=eq.true&select=id,full_name,job_title,role"),
        selectRecords("pr_quotations","select=*&order=created_at.desc&limit=100")
      ]);
      setItems(requestsData); setEmployees(staffData); setQuotes(quotesData);
    } catch(e) { notify(e instanceof Error ? e.message : "تعذر تحميل دورة التشغيل"); }
    finally { setLoading(false); }
  };
  useEffect(() => { void load(); }, []);
  const action = async (requestId:string,actionName:string) => {
    try {
      await callRpc("pr_admin_workflow",{ p_request_id:requestId,p_action:actionName,p_amount:amounts[requestId] ? Number(amounts[requestId]) : null,p_employee_id:assignees[requestId] || null,p_note:null });
      notify(actionName==="invoice" ? "تم إصدار الفاتورة" : "تم تحديث مرحلة الخدمة");
      await load();
    } catch(e) { notify(e instanceof Error ? e.message : "تعذر تنفيذ الإجراء"); }
  };
  return <div className="page management"><section className="pagehead"><div><p>من الطلب حتى التحصيل</p><h1>دورة تشغيل الخدمة</h1><span>متابعة العميل والفريق والعرض والتنفيذ والفاتورة في مسار واحد.</span></div></section>
    <section className="workflowSteps">{["طلب جديد","مراجعة","عرض سعر","اعتماد العميل","إسناد موظف","تنفيذ","فاتورة وتحصيل"].map((x,i)=><div key={x}><b>{i+1}</b><span>{x}</span></div>)}</section>
    {loading ? <div className="emptyState">جاري تحميل الطلبات...</div> : !items.length ? <div className="emptyState">لا توجد طلبات خدمة بعد</div> : <section className="workflowList">{items.map(r => { const id=String(r.id); const status=String(r.status||"new"); return <article className="workflowCard" key={id}><header><div><small>{String(r.request_no||"طلب")}</small><h3>{String(r.customer_name||"عميل")} — {String(r.service_type||"خدمة")}</h3><p>{String(r.address||r.city||"جدة")}</p></div><span className={"stage "+status}>{workflowLabels[status]||status}</span></header><div className="workflowActions">
      {status==="new" && <button onClick={()=>action(id,"review")}>بدء المراجعة</button>}
      {status==="reviewing" && <button onClick={()=>setQuoteRequest(r)}>إعداد ومراجعة عرض السعر</button>}
      {status==="quoted" && <><em>تم الإرسال وبانتظار اعتماد العميل</em><button onClick={()=>setQuoteRequest(r)}>معاينة العرض</button></>}
      {status==="approved" && <><label><span>الموظف المسؤول</span><select value={assignees[id]||""} onChange={e=>setAssignees({...assignees,[id]:e.target.value})}><option value="">اختر الموظف</option>{employees.map(e=><option key={String(e.id)} value={String(e.id)}>{String(e.full_name||"موظف")} — {String(e.job_title||roleArabic(String(e.role)))}</option>)}</select></label><button onClick={()=>action(id,"assign")}>إسناد وجدولة</button></>}
      {status==="scheduled" && <button onClick={()=>action(id,"start")}>بدء التنفيذ</button>}
      {status==="in_progress" && <button onClick={()=>action(id,"complete")}>إنهاء الخدمة</button>}
      {status==="completed" && <><label><span>قيمة الفاتورة قبل الضريبة</span><input type="number" min="1" value={amounts[id]||String(Number(r.quoted_total||0)/1.15||"")} onChange={e=>setAmounts({...amounts,[id]:e.target.value})}/></label><button onClick={()=>action(id,"invoice")}>إصدار الفاتورة</button></>}
    </div></article>; })}</section>}
    <QuoteEditor request={quoteRequest} quote={quoteRequest?quotes.find(q=>String(q.request_id)===String(quoteRequest.id))||null:null} onClose={()=>setQuoteRequest(null)} onChanged={load} notify={notify}/>
  </div>;
}

type QuoteLine={category?:string;description:string;descriptionEn:string;quantity:string;unit:string;unitPrice:string};
function QuoteEditor({request,quote,onClose,onChanged,notify}:{request:Record<string,unknown>|null;quote:Record<string,unknown>|null;onClose:()=>void;onChanged:()=>Promise<void>;notify:(m:string)=>void}){
  const [language,setLanguage]=useState<"ar"|"en">("ar");
  const [liveQuote,setLiveQuote]=useState<Record<string,unknown>|null>(quote);
  const [draft,setDraft]=useState({scopeAr:"",scopeEn:"",termsAr:"",termsEn:"",validDays:"14",discount:"0"});
  const [vatRate,setVatRate]=useState("15");
  const [lines,setLines]=useState<QuoteLine[]>([{category:"خدمات تنظيف",description:"",descriptionEn:"",quantity:"1",unit:"خدمة",unitPrice:""}]);
  const [saving,setSaving]=useState(false);
  useEffect(()=>{setLiveQuote(quote);if(!request)return;setDraft({scopeAr:String(quote?.scope||request.service_type||""),scopeEn:String(quote?.scope_en||"Professional cleaning services"),termsAr:String(quote?.terms||"صلاحية العرض 14 يومًا. يبدأ التنفيذ بعد اعتماد العميل والاتفاق على الموعد."),termsEn:String(quote?.terms_en||"Quotation is valid for 14 days. Work starts after client approval and schedule confirmation."),validDays:String(quote?.valid_days||14),discount:String(quote?.discount||0)});if(quote?.id){selectRecords("pr_quotation_items",`quotation_id=eq.${quote.id}&select=*&order=sort_order.asc`).then(rows=>setLines(rows.length?rows.map(x=>({description:String(x.description||""),descriptionEn:String(x.description_en||""),quantity:String(x.quantity||1),unit:String(x.unit||"خدمة"),unitPrice:String(x.unit_price||0)})):[{description:"",descriptionEn:"",quantity:"1",unit:"خدمة",unitPrice:""}])).catch(()=>undefined);}else setLines([{description:String(request.service_type||""),descriptionEn:"Professional cleaning service",quantity:"1",unit:"خدمة",unitPrice:""}]);},[request,quote]);
  useEffect(()=>{setVatRate(String(quote?.vat_rate||15));},[quote]);
  useEffect(()=>{if(!quote?.id)return;selectRecords("pr_quotation_items",`quotation_id=eq.${quote.id}&select=*&order=sort_order.asc`).then(rows=>setLines(rows.map(x=>({category:String(x.category||"خدمات تنظيف"),description:String(x.description||""),descriptionEn:String(x.description_en||""),quantity:String(x.quantity||1),unit:String(x.unit||"خدمة"),unitPrice:String(x.unit_price||0)})))).catch(()=>undefined);},[quote?.id]);
  if(!request)return null;
  const subtotal=lines.reduce((s,x)=>s+(Number(x.quantity)||0)*(Number(x.unitPrice)||0),0),discount=Math.min(Number(draft.discount)||0,subtotal),taxable=subtotal-discount,vat=taxable*(Number(vatRate)||0)/100,total=taxable+vat;
  const editable=!liveQuote||liveQuote.status==="draft";
  const setLine=(index:number,key:keyof QuoteLine,value:string)=>setLines(lines.map((x,i)=>i===index?{...x,[key]:value}:x));
  const addLine=()=>setLines([...lines,{category:"خدمات تنظيف",description:"",descriptionEn:"",quantity:"1",unit:"خدمة",unitPrice:""}]);
  const save=async()=>{if(!lines.length||lines.some(x=>!x.description.trim()||Number(x.quantity)<=0||Number(x.unitPrice)<0)||subtotal<=0){notify("أكمل الصنف والوصف والكمية والسعر لجميع البنود");return;}setSaving(true);try{await callRpc("pr_save_detailed_quote_draft",{p_request_id:request.id,p_items:lines.map(x=>({category:x.category||"خدمات تنظيف",description:x.description,description_en:x.descriptionEn,quantity:Number(x.quantity),unit:x.unit,unit_price:Number(x.unitPrice)})),p_discount:discount,p_vat_rate:Number(vatRate),p_scope_ar:draft.scopeAr,p_scope_en:draft.scopeEn,p_terms_ar:draft.termsAr,p_terms_en:draft.termsEn,p_valid_days:Number(draft.validDays)});const saved=await selectRecords("pr_quotations",`request_id=eq.${request.id}&status=eq.draft&select=*&order=updated_at.desc&limit=1`);setLiveQuote(saved[0]||null);notify("تم حفظ عرض السعر التفصيلي كمسودة");await onChanged();}catch(e){notify(e instanceof Error?e.message:"تعذر حفظ المسودة");}finally{setSaving(false);}};
  const send=async()=>{if(!liveQuote?.id){notify("احفظ المسودة أولًا");return;}try{await callRpc("pr_send_quote",{p_quote_id:liveQuote.id});notify("تم إرسال عرض السعر للعميل");await onChanged();onClose();}catch(e){notify(e instanceof Error?e.message:"تعذر إرسال العرض");}};
  const safe=(v:unknown)=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]||c));
  const documentHtml=()=>{const rtl=language==="ar",labels=rtl?{title:"عرض سعر",client:"طالب الخدمة",location:"الموقع",desc:"البيان",qty:"الكمية",unit:"الوحدة",price:"سعر الوحدة",line:"الإجمالي",sub:"المجموع",discount:"الخصم",vat:"ضريبة القيمة المضافة 15%",total:"الإجمالي شامل الضريبة",scope:"نطاق العمل",terms:"الشروط والأحكام"}:{title:"QUOTATION",client:"Requested by",location:"Location",desc:"Description",qty:"Qty",unit:"Unit",price:"Unit price",line:"Line total",sub:"Subtotal",discount:"Discount",vat:"VAT 15%",total:"Total incl. VAT",scope:"Scope of work",terms:"Terms and conditions"};return `<!doctype html><html dir="${rtl?"rtl":"ltr"}"><head><meta charset="utf-8"><title>${safe(liveQuote?.quote_no||labels.title)}</title><style>body{font-family:Arial,sans-serif;color:#0d2c45;margin:35px}header{display:flex;justify-content:space-between;border-bottom:3px solid #18b8c6;padding-bottom:15px}img{width:130px}h1{margin:0}.party{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:25px 0}.party div{display:grid;gap:6px}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{border:1px solid #cbdadd;padding:10px;text-align:${rtl?"right":"left"}}tfoot th{background:#eaf6f7}.block{white-space:pre-wrap;border:1px solid #d9e4e6;padding:14px;margin:15px 0}footer{text-align:center;margin-top:30px;color:#63777e}@media print{body{margin:12mm}}</style></head><body><header><img src="${location.origin}/brand/logo.png"><div><h1>${labels.title}</h1><b>${safe(liveQuote?.quote_no||(rtl?"مسودة":"DRAFT"))}</b><p>${safe(liveQuote?.issue_date||new Date().toISOString().slice(0,10))}</p></div></header><section class="party"><div><small>${labels.client}</small><b>${safe(request.customer_name)}</b><span>${safe(request.customer_phone)}</span><span>${safe(request.customer_email)}</span></div><div><small>${labels.location}</small><b>${safe(request.address||request.district||request.city)}</b></div></section><div class="block"><b>${labels.scope}</b><br>${safe(rtl?draft.scopeAr:draft.scopeEn)}</div><table><thead><tr><th>#</th><th>${labels.desc}</th><th>${labels.qty}</th><th>${labels.unit}</th><th>${labels.price}</th><th>${labels.line}</th></tr></thead><tbody>${lines.map((x,i)=>`<tr><td>${i+1}</td><td>${safe(rtl?x.description:x.descriptionEn||x.description)}</td><td>${safe(x.quantity)}</td><td>${safe(x.unit)}</td><td>${Number(x.unitPrice).toFixed(2)}</td><td>${((Number(x.quantity)||0)*(Number(x.unitPrice)||0)).toFixed(2)}</td></tr>`).join("")}</tbody><tfoot><tr><th colspan="5">${labels.sub}</th><th>${subtotal.toFixed(2)}</th></tr><tr><th colspan="5">${labels.discount}</th><th>${discount.toFixed(2)}</th></tr><tr><th colspan="5">${labels.vat}</th><th>${vat.toFixed(2)}</th></tr><tr><th colspan="5">${labels.total}</th><th>${total.toFixed(2)} SAR</th></tr></tfoot></table><div class="block"><b>${labels.terms}</b><br>${safe(rtl?draft.termsAr:draft.termsEn)}</div><footer>Purity Ritual · +966 55 533 0406 · ahmedazi911@gmail.com</footer></body></html>`;};
  const printPdf=()=>{const popup=window.open("","_blank","width=1000,height=800");if(!popup){notify("اسمح بالنوافذ المنبثقة للطباعة");return;}popup.document.open();popup.document.write(documentHtml());popup.document.close();window.setTimeout(()=>{popup.focus();popup.print();},900);};
  const exportExcel=()=>{const rtl=language==="ar",heads=rtl?["الصنف","البيان","الكمية","الوحدة","سعر الوحدة","الإجمالي"]:["Category","Description","Quantity","Unit","Unit price","Total"];const itemRows=lines.map(x=>`<tr><td>${safe(x.category)}</td><td>${safe(rtl?x.description:x.descriptionEn||x.description)}</td><td>${safe(x.quantity)}</td><td>${safe(x.unit)}</td><td>${Number(x.unitPrice).toFixed(2)}</td><td>${((Number(x.quantity)||0)*(Number(x.unitPrice)||0)).toFixed(2)}</td></tr>`).join("");const html=`<html><head><meta charset="utf-8"></head><body><table border="1"><tr><th>${rtl?"رقم العرض":"Quotation No."}</th><td>${safe(liveQuote?.quote_no||"DRAFT")}</td></tr><tr><th>${rtl?"طالب الخدمة":"Requested by"}</th><td>${safe(request.customer_name)}</td></tr><tr><th>${rtl?"الجوال":"Phone"}</th><td>${safe(request.customer_phone)}</td></tr><tr><th>${rtl?"البريد":"Email"}</th><td>${safe(request.customer_email)}</td></tr></table><br><table border="1"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${itemRows}</tbody><tfoot><tr><th colspan="5">${rtl?"المجموع":"Subtotal"}</th><th>${subtotal.toFixed(2)}</th></tr><tr><th colspan="5">${rtl?"الخصم":"Discount"}</th><th>${discount.toFixed(2)}</th></tr><tr><th colspan="5">${rtl?"الضريبة":"VAT"} ${safe(vatRate)}%</th><th>${vat.toFixed(2)}</th></tr><tr><th colspan="5">${rtl?"الإجمالي":"Total"}</th><th>${total.toFixed(2)} SAR</th></tr></tfoot></table></body></html>`;const url=URL.createObjectURL(new Blob([html],{type:"application/vnd.ms-excel;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=`${String(liveQuote?.quote_no||"Purity-Ritual-Quotation")}-${language}.xls`;document.body.appendChild(a);a.click();a.remove();window.setTimeout(()=>URL.revokeObjectURL(url),1000);};
  return <Dialog open={Boolean(request)} onOpenChange={v=>!v&&onClose()}><DialogContent dir={language==="ar"?"rtl":"ltr"} className="quoteDialog"><DialogHeader><DialogTitle>{editable?(language==="ar"?"عرض سعر تفصيلي قبل الإرسال":"Detailed quotation before sending"):(language==="ar"?"معاينة عرض السعر":"Quotation preview")}</DialogTitle><DialogDescription>{language==="ar"?"أضف البنود وراجع الإجماليات، ثم احفظ المسودة وأرسلها للعميل.":"Add line items, review totals, save the draft, then send it to the client."}</DialogDescription></DialogHeader><div className="documentTools"><button onClick={()=>setLanguage("ar")} className={language==="ar"?"active":""}>العربية</button><button onClick={()=>setLanguage("en")} className={language==="en"?"active":""}>English</button><button onClick={printPdf}><Download/>{language==="ar"?"طباعة / PDF":"Print / PDF"}</button><button onClick={exportExcel}><Download/>Excel</button><label className="vatControl"><span>{language==="ar"?"الضريبة %":"VAT %"}</span><input type="number" min="0" max="100" disabled={!editable} value={vatRate} onChange={e=>setVatRate(e.target.value)}/></label></div>
    <section className="quotePrintCard"><header><img src="/brand/logo.png" alt="Purity Ritual"/><div><h2>{language==="ar"?"عرض سعر":"QUOTATION"}</h2><strong>{String(liveQuote?.quote_no||(language==="ar"?"مسودة":"DRAFT"))}</strong></div></header><div className="quoteParties"><div><small>{language==="ar"?"طالب الخدمة":"Requested by"}</small><strong>{String(request.customer_name||"")}</strong><span>{String(request.customer_phone||"")}</span><span>{String(request.customer_email||"")}</span></div><div><small>{language==="ar"?"الموقع":"Location"}</small><strong>{String(request.address||request.district||request.city||"")}</strong><span>{language==="ar"?"التاريخ":"Date"}: {String(liveQuote?.issue_date||new Date().toISOString().slice(0,10))}</span></div></div><label className="quoteField"><span>{language==="ar"?"نطاق العمل":"Scope of work"}</span><textarea disabled={!editable} value={language==="ar"?draft.scopeAr:draft.scopeEn} onChange={e=>setDraft(language==="ar"?{...draft,scopeAr:e.target.value}:{...draft,scopeEn:e.target.value})}/></label>
      <div className="quoteItems"><table><thead><tr><th>#</th><th>{language==="ar"?"الصنف":"Category"}</th><th>{language==="ar"?"البيان":"Description"}</th><th>{language==="ar"?"الكمية":"Qty"}</th><th>{language==="ar"?"الوحدة":"Unit"}</th><th>{language==="ar"?"سعر الوحدة":"Unit price"}</th><th>{language==="ar"?"الإجمالي":"Total"}</th>{editable&&<th/>}</tr></thead><tbody>{lines.map((x,i)=><tr key={i}><td>{i+1}</td><td><select disabled={!editable} value={x.category||"خدمات تنظيف"} onChange={e=>setLine(i,"category",e.target.value)}><option>خدمات تنظيف</option><option>مواد ومستهلكات</option><option>معدات</option><option>عمالة إضافية</option><option>نقل</option><option>أعمال إضافية</option></select></td><td><input disabled={!editable} value={language==="ar"?x.description:x.descriptionEn} onChange={e=>setLine(i,language==="ar"?"description":"descriptionEn",e.target.value)} placeholder={language==="ar"?"وصف البند":"Item description"}/></td><td><input type="number" min=".01" step=".01" disabled={!editable} value={x.quantity} onChange={e=>setLine(i,"quantity",e.target.value)}/></td><td><input disabled={!editable} value={x.unit} onChange={e=>setLine(i,"unit",e.target.value)}/></td><td><input type="number" min="0" step=".01" disabled={!editable} value={x.unitPrice} onChange={e=>setLine(i,"unitPrice",e.target.value)}/></td><td>{((Number(x.quantity)||0)*(Number(x.unitPrice)||0)).toLocaleString("ar-SA")}</td>{editable&&<td><button className="removeLine" onClick={()=>setLines(lines.filter((_,n)=>n!==i))}>×</button></td>}</tr>)}</tbody></table>{editable&&<button className="addLine" onClick={addLine}><Plus/>إضافة بند</button>}</div>
      <div className="quoteTotals"><label><span>{language==="ar"?"الخصم":"Discount"}</span><input type="number" min="0" disabled={!editable} value={draft.discount} onChange={e=>setDraft({...draft,discount:e.target.value})}/></label><p><span>{language==="ar"?"المجموع":"Subtotal"}</span><b>{subtotal.toLocaleString("ar-SA")} ر.س</b></p><p><span>{language==="ar"?"بعد الخصم":"After discount"}</span><b>{taxable.toLocaleString("ar-SA")} ر.س</b></p><p><span>{language==="ar"?"الضريبة 15%":"VAT 15%"}</span><b>{vat.toLocaleString("ar-SA")} ر.س</b></p><p className="grand"><span>{language==="ar"?"الإجمالي":"Total"}</span><b>{total.toLocaleString("ar-SA")} ر.س</b></p></div><div className="quoteEditGrid"><label><span>{language==="ar"?"صلاحية العرض بالأيام":"Validity days"}</span><input type="number" min="1" disabled={!editable} value={draft.validDays} onChange={e=>setDraft({...draft,validDays:e.target.value})}/></label></div><label className="quoteField"><span>{language==="ar"?"الشروط والأحكام":"Terms and conditions"}</span><textarea disabled={!editable} value={language==="ar"?draft.termsAr:draft.termsEn} onChange={e=>setDraft(language==="ar"?{...draft,termsAr:e.target.value}:{...draft,termsEn:e.target.value})}/></label><footer>Purity Ritual · +966 55 533 0406 · ahmedazi911@gmail.com</footer></section>
    {editable&&<div className="quoteActions"><button className="secondaryAction" disabled={saving} onClick={save}>{saving?"جاري الحفظ...":"حفظ المسودة"}</button><button className="primary" disabled={!liveQuote?.id} onClick={send}><Send/>إرسال للعميل</button></div>}
  </DialogContent></Dialog>;
}

function QuotationBoard({notify}:{notify:(m:string)=>void}){
  const [quotes,setQuotes]=useState<Record<string,unknown>[]>([]);
  const [requestsData,setRequestsData]=useState<Record<string,unknown>[]>([]);
  const [loadError,setLoadError]=useState("");
  const [selected,setSelected]=useState<Record<string,unknown>|null>(null);
  const [pickerOpen,setPickerOpen]=useState(false);
  const [pendingRequestId,setPendingRequestId]=useState("");
  const [editorRequestId,setEditorRequestId]=useState("");
  const load=async()=>{setLoadError("");const result=await Promise.allSettled([selectRecords("pr_quotations","select=*&order=created_at.desc"),selectRecords("pr_service_requests","select=*&order=created_at.desc")]);if(result[0].status==="fulfilled")setQuotes(result[0].value);else setLoadError("تعذر تحميل عروض الأسعار — تحقق من صلاحية المبيعات");if(result[1].status==="fulfilled")setRequestsData(result[1].value);else setLoadError("تعذر تحميل العملاء وطلبات الخدمة — تحقق من صلاحية قراءة الطلبات");};
  useEffect(()=>{void load();},[]);
  const eligible=requestsData.filter(r=>{
    const status=String(r.status||"new");
    const related=quotes.filter(q=>String(q.request_id)===String(r.id));
    const hasFinalQuote=related.some(q=>["sent","accepted"].includes(String(q.status)));
    return !["cancelled","closed","completed"].includes(status)&&(!hasFinalQuote||related.some(q=>q.status==="draft"));
  });
  const activeRequestId=selected?String(selected.request_id):editorRequestId;
  const request=activeRequestId?requestsData.find(r=>String(r.id)===activeRequestId)||null:null;
  const activeQuote=selected||(editorRequestId?quotes.find(q=>String(q.request_id)===editorRequestId&&q.status==="draft")||null:null);
  const closeEditor=()=>{setSelected(null);setEditorRequestId("");};
  return <div className="page management">
    <section className="pagehead"><div><p>المبيعات</p><h1>عروض الأسعار</h1><span>إنشاء ومراجعة عروض الأسعار التفصيلية قبل إرسالها للعميل.</span></div><button className="primary" onClick={()=>setPickerOpen(true)}><Plus/>إنشاء عرض سعر</button></section>
    <section className="panel dataPanel"><div className="tablewrap"><table className="managementTable"><thead><tr><th>رقم العرض</th><th>طالب الخدمة</th><th>الإجمالي</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{quotes.map(q=><tr key={String(q.id)}><td>{String(q.quote_no||"مسودة")}</td><td>{String(q.customer_name||"—")}</td><td>{Number(q.total||0).toLocaleString("ar-SA")} ر.س</td><td>{q.status==="draft"?"مسودة — لم ترسل":q.status==="sent"?"مرسل للعميل":q.status==="accepted"?"معتمد":q.status==="rejected"?"مرفوض":String(q.status)}</td><td><button className="rowAction" onClick={()=>setSelected(q)}><Eye/>{q.status==="draft"?"مراجعة وتعديل":"عرض وتصدير"}</button></td></tr>)}</tbody></table></div>{!quotes.length&&<div className="emptyState">لا توجد عروض حتى الآن. اضغط «إنشاء عرض سعر» للبدء.</div>}</section>
    <Dialog open={pickerOpen} onOpenChange={setPickerOpen}><DialogContent dir="rtl" className="createDialog"><DialogHeader><DialogTitle>إنشاء عرض سعر</DialogTitle><DialogDescription>اختر طلب الخدمة؛ تظهر معه بيانات العميل المسجلة تلقائيًا.</DialogDescription></DialogHeader><div className="createForm"><label><span>طلب الخدمة / طالب الخدمة</span><select value={pendingRequestId} onChange={e=>setPendingRequestId(e.target.value)}><option value="">اختر الطلب</option>{eligible.map(r=><option key={String(r.id)} value={String(r.id)}>{String(r.request_no||"طلب")} — {String(r.customer_name||"عميل")} — {String(r.customer_phone||"")} — {String(r.service_type||"")}</option>)}</select></label>{loadError&&<p className="formError">{loadError}</p>}{!loadError&&!eligible.length&&<p className="formError">لا توجد طلبات متاحة للتسعير. حوّل طلب عرض السعر إلى طلب خدمة أولًا.</p>}<button className="primary" disabled={!pendingRequestId} onClick={()=>{setEditorRequestId(pendingRequestId);setPickerOpen(false);}}>فتح فورم عرض السعر</button></div></DialogContent></Dialog>
    <QuoteEditor request={request} quote={activeQuote} onClose={closeEditor} onChanged={load} notify={notify}/>
  </div>;
}

function ProjectControlBoard({ notify }: { notify:(m:string)=>void }) {
  const [requestsData,setRequestsData]=useState<Record<string,unknown>[]>([]);
  const [staff,setStaff]=useState<Record<string,unknown>[]>([]);
  const [members,setMembers]=useState<Record<string,unknown>[]>([]);
  const [expenses,setExpenses]=useState<Record<string,unknown>[]>([]);
  const [events,setEvents]=useState<Record<string,unknown>[]>([]);
  const [selectedRequest,setSelectedRequest]=useState("");
  const [memberOpen,setMemberOpen]=useState(false);
  const [expenseOpen,setExpenseOpen]=useState(false);
  const load=async()=>{
    const r=await Promise.allSettled([
      selectRecords("pr_service_requests","select=*&order=created_at.desc&limit=100"),
      selectRecords("pr_profiles","role=in.(manager,operations)&is_active=eq.true&select=id,full_name,job_title"),
      selectRecords("pr_project_members","select=*&order=created_at.desc"),
      selectRecords("pr_project_expenses","select=*&order=expense_date.desc"),
      selectRecords("pr_activity_log","select=*&order=created_at.desc&limit=40")
    ]);
    if(r[0].status==="fulfilled")setRequestsData(r[0].value);
    if(r[1].status==="fulfilled")setStaff(r[1].value);
    if(r[2].status==="fulfilled")setMembers(r[2].value);
    if(r[3].status==="fulfilled")setExpenses(r[3].value);
    if(r[4].status==="fulfilled")setEvents(r[4].value);
  };
  useEffect(()=>{void load();},[]);
  const addMember=async(event:React.FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);try{await callRpc("pr_add_project_member",{p_request_id:data.get("request_id"),p_employee_id:data.get("employee_id"),p_team_role:data.get("team_role")});notify("تمت إضافة الموظف إلى فريق المشروع");setMemberOpen(false);await load();}catch(e){notify(e instanceof Error?e.message:"تعذر إضافة الموظف");}};
  const addExpense=async(event:React.FormEvent<HTMLFormElement>)=>{event.preventDefault();const data=new FormData(event.currentTarget);try{await callRpc("pr_add_project_expense",{p_request_id:data.get("request_id"),p_category:data.get("category"),p_description:data.get("description"),p_amount:Number(data.get("amount")),p_reference:data.get("reference")||null});notify("تم تسجيل المصروف واعتماد أثره على الربحية");setExpenseOpen(false);await load();}catch(e){notify(e instanceof Error?e.message:"تعذر تسجيل المصروف");}};
  const visibleRequests=selectedRequest?requestsData.filter(r=>String(r.id)===selectedRequest):requestsData;
  const totalRevenue=requestsData.reduce((s,r)=>s+Number(r.quoted_total||0),0);
  const totalCost=expenses.reduce((s,e)=>s+Number(e.amount||0),0);
  const staffName=(id:unknown)=>String(staff.find(x=>String(x.id)===String(id))?.full_name||"موظف");
  return <div className="page management"><section className="pagehead"><div><p>رقابة التشغيل</p><h1>فرق المشاريع والتكاليف</h1><span>فريق التنفيذ والمصروفات والربحية وسجل التغييرات من بيانات النظام الفعلية.</span></div><div className="headActions"><button className="secondaryAction" onClick={()=>setMemberOpen(true)}>إضافة للفريق</button><button className="primary" onClick={()=>setExpenseOpen(true)}><Plus/>تسجيل مصروف</button></div></section>
    <section className="stats"><Stat label="قيمة المشاريع" value={totalRevenue.toLocaleString("ar-SA")} note="ر.س شاملة الضريبة" icon={<WalletCards/>}/><Stat label="تكلفة التنفيذ" value={totalCost.toLocaleString("ar-SA")} note="ر.س مصروفات فعلية" icon={<ReceiptText/>}/><Stat label="هامش الربح" value={(totalRevenue-totalCost).toLocaleString("ar-SA")} note="قبل المصاريف العامة" icon={<TrendingUp/>}/><Stat label="أعضاء الفرق" value={String(members.length)} note="إسنادات مسجلة" icon={<Users/>}/></section>
    <section className="panel controlFilter"><label><span>تصفية حسب المشروع</span><select value={selectedRequest} onChange={e=>setSelectedRequest(e.target.value)}><option value="">جميع المشاريع</option>{requestsData.map(r=><option key={String(r.id)} value={String(r.id)}>{String(r.request_no||"طلب")} — {String(r.customer_name||"عميل")}</option>)}</select></label></section>
    <section className="controlGrid"><div className="panel"><h2>فرق التنفيذ</h2>{visibleRequests.length?visibleRequests.map(r=>{const assigned=members.filter(m=>String(m.request_id)===String(r.id));return <article className="controlProject" key={String(r.id)}><header><strong>{String(r.request_no||"طلب")}</strong><span>{String(r.customer_name||"")}</span></header>{assigned.length?<div>{assigned.map(m=><span className="memberChip" key={String(m.id)}>{staffName(m.employee_id)} · {String(m.team_role||"عضو فريق")}</span>)}</div>:<small>لم يُشكّل فريق لهذا المشروع بعد</small>}</article>}):<div className="emptyState">لا توجد مشاريع حقيقية</div>}</div>
      <div className="panel"><h2>المصروفات</h2>{expenses.filter(e=>!selectedRequest||String(e.request_id)===selectedRequest).length?expenses.filter(e=>!selectedRequest||String(e.request_id)===selectedRequest).map(e=><article className="reportRow" key={String(e.id)}><div><strong>{String(e.category)}</strong><span>{String(e.description)} · {String(e.expense_date)}</span></div><b>{Number(e.amount||0).toLocaleString("ar-SA")} ر.س</b></article>):<div className="emptyState">لا توجد مصروفات مسجلة</div>}</div>
      <div className="panel auditPanel"><h2>سجل التدقيق</h2>{events.filter(e=>!selectedRequest||String(e.request_id)===selectedRequest).length?events.filter(e=>!selectedRequest||String(e.request_id)===selectedRequest).map(e=><article className="auditRow" key={String(e.id)}><i/><div><strong>{String(e.action_label||e.action)}</strong><span>{new Date(String(e.created_at)).toLocaleString("ar-SA")}</span></div></article>):<div className="emptyState">لا توجد تغييرات مسجلة</div>}</div></section>
    <Dialog open={memberOpen} onOpenChange={setMemberOpen}><DialogContent dir="rtl" className="createDialog"><DialogHeader><DialogTitle>إضافة موظف إلى فريق مشروع</DialogTitle><DialogDescription>يمكن للمشروع أن يضم أكثر من موظف مع تحديد دور كل شخص.</DialogDescription></DialogHeader><form className="createForm" onSubmit={addMember}><label><span>المشروع</span><select name="request_id" required><option value="">اختر المشروع</option>{requestsData.map(r=><option key={String(r.id)} value={String(r.id)}>{String(r.request_no||"طلب")} — {String(r.customer_name||"")}</option>)}</select></label><label><span>الموظف</span><select name="employee_id" required><option value="">اختر الموظف</option>{staff.map(s=><option key={String(s.id)} value={String(s.id)}>{String(s.full_name)} — {String(s.job_title||"فريق التنفيذ")}</option>)}</select></label><label><span>الدور في الفريق</span><select name="team_role"><option value="قائد فريق">قائد فريق</option><option value="مشرف موقع">مشرف موقع</option><option value="فني نظافة">فني نظافة</option><option value="سائق ومساندة">سائق ومساندة</option></select></label><button className="primary">حفظ الإسناد</button></form></DialogContent></Dialog>
    <Dialog open={expenseOpen} onOpenChange={setExpenseOpen}><DialogContent dir="rtl" className="createDialog"><DialogHeader><DialogTitle>تسجيل مصروف مشروع</DialogTitle><DialogDescription>يظهر المصروف مباشرة في تكلفة المشروع وهامش الربح.</DialogDescription></DialogHeader><form className="createForm" onSubmit={addExpense}><label><span>المشروع</span><select name="request_id" required><option value="">اختر المشروع</option>{requestsData.map(r=><option key={String(r.id)} value={String(r.id)}>{String(r.request_no||"طلب")} — {String(r.customer_name||"")}</option>)}</select></label><div className="formGrid"><label><span>التصنيف</span><select name="category"><option value="مواد تنظيف">مواد تنظيف</option><option value="أجور فريق">أجور فريق</option><option value="نقل">نقل</option><option value="معدات">معدات</option><option value="أخرى">أخرى</option></select></label><label><span>المبلغ (ر.س)</span><input name="amount" type="number" min="0.01" step="0.01" required/></label></div><label><span>البيان</span><input name="description" required/></label><label><span>رقم المرجع أو الإيصال</span><input name="reference"/></label><button className="primary">حفظ المصروف</button></form></DialogContent></Dialog>
  </div>;
}

function LeadBoard({ notify }: { notify:(m:string)=>void }) {
  const [leads,setLeads]=useState<Record<string,unknown>[]>([]);
  const [loading,setLoading]=useState(true);
  const load=()=>selectRecords("pr_public_quote_requests","select=*&order=created_at.desc").then(setLeads).catch(e=>notify(e instanceof Error?e.message:"تعذر تحميل الطلبات")).finally(()=>setLoading(false));
  useEffect(()=>{void load();},[]);
  const convert=async(id:string)=>{try{await callRpc("pr_convert_quote_request",{p_public_id:id});notify("تم تحويل الطلب إلى إدارة المشاريع والتسعير");await load();}catch(e){notify(e instanceof Error?e.message:"تعذر تحويل الطلب");}};
  return <div className="page management"><section className="pagehead"><div><p>المبيعات والتسويق</p><h1>طلبات عروض السعر</h1><span>طلبات حقيقية واردة من الموقع، جاهزة للتأهيل والتحويل للمشاريع.</span></div></section>{loading?<div className="emptyState">جاري التحميل...</div>:!leads.length?<div className="emptyState">لا توجد طلبات عروض سعر حقيقية</div>:<section className="leadGrid">{leads.map(l=><article key={String(l.id)}><header><div><small>{new Date(String(l.created_at)).toLocaleDateString("ar-SA")}</small><h3>{String(l.full_name)}</h3></div><span>{l.status==="converted"?"محول للمشاريع":l.status==="followup"?"قيد المتابعة":"جديد"}</span></header><p>{String(l.service_type)} — {String(l.district||l.city||"جدة")}</p><div><a href={`tel:${l.phone}`}><Phone/>اتصال</a><a href={`https://wa.me/${String(l.phone).replace(/\D/g,"")}`} target="_blank" rel="noreferrer">واتساب</a>{!l.converted_request_id&&<button onClick={()=>convert(String(l.id))}>تحويل لإدارة المشاريع</button>}</div></article>)}</section>}</div>;
}

function FollowupBoard({ notify }: { notify:(m:string)=>void }) {
  const [leads,setLeads]=useState<Record<string,unknown>[]>([]);
  const [notes,setNotes]=useState<Record<string,string>>({});
  const [dates,setDates]=useState<Record<string,string>>({});
  const load=()=>selectRecords("pr_public_quote_requests","select=*&order=created_at.desc").then(setLeads).catch(e=>notify(e instanceof Error?e.message:"تعذر تحميل المتابعات"));
  useEffect(()=>{void load();},[]);
  const save=async(l:Record<string,unknown>)=>{const id=String(l.id);if(!notes[id]){notify("اكتب نتيجة المتابعة");return;}try{await callRpc("pr_add_followup",{p_public_id:id,p_request_id:l.converted_request_id||null,p_channel:"phone",p_note:notes[id],p_outcome:"contacted",p_next:dates[id]?new Date(dates[id]).toISOString():null});notify("تم حفظ متابعة العميل");setNotes({...notes,[id]:""});await load();}catch(e){notify(e instanceof Error?e.message:"تعذر حفظ المتابعة");}};
  return <div className="page management"><section className="pagehead"><div><p>خدمة العملاء والتسويق</p><h1>متابعة العملاء</h1><span>سجل الاتصالات والنتائج وموعد المتابعة القادمة لكل عميل.</span></div></section>{!leads.length?<div className="emptyState">لا توجد عملاء للمتابعة</div>:<section className="followupList">{leads.map(l=>{const id=String(l.id);return <article key={id}><div><h3>{String(l.full_name)}</h3><p>{String(l.phone)} — {String(l.service_type)}</p><small>{l.next_followup_at?`المتابعة القادمة: ${new Date(String(l.next_followup_at)).toLocaleString("ar-SA")}`:"لم تحدد متابعة قادمة"}</small></div><input value={notes[id]||""} onChange={e=>setNotes({...notes,[id]:e.target.value})} placeholder="نتيجة الاتصال أو الملاحظة"/><input type="datetime-local" value={dates[id]||""} onChange={e=>setDates({...dates,[id]:e.target.value})}/><button onClick={()=>save(l)}>حفظ المتابعة</button></article>})}</section>}</div>;
}

function ReportsBoard({ notify }: { notify:(m:string)=>void }) {
  const [requestsData,setRequestsData]=useState<Record<string,unknown>[]>([]);
  const [invoices,setInvoices]=useState<Record<string,unknown>[]>([]);
  const [payments,setPayments]=useState<Record<string,unknown>[]>([]);
  const [selected,setSelected]=useState<Record<string,unknown>|null>(null);
  const load=async()=>{const r=await Promise.allSettled([selectRecords("pr_service_requests","select=*&order=created_at.desc"),selectRecords("pr_invoices","select=*&order=created_at.desc"),selectRecords("pr_payments","select=*&order=created_at.desc")]);if(r[0].status==="fulfilled")setRequestsData(r[0].value);if(r[1].status==="fulfilled")setInvoices(r[1].value);if(r[2].status==="fulfilled")setPayments(r[2].value);};
  useEffect(()=>{void load();},[]);
  const billed=invoices.reduce((s,i)=>s+Number(i.total||0),0),collected=payments.reduce((s,p)=>s+Number(p.amount||0),0);
  const close=async(id:string)=>{try{await callRpc("pr_close_service_request",{p_request_id:id});notify("تم إغلاق الطلب ماليًا وتشغيليًا");await load();}catch(e){notify(e instanceof Error?e.message:"تعذر إغلاق الطلب");}};
  return <div className="page management"><section className="pagehead"><div><p>تقارير فعلية</p><h1>التقارير والإغلاق</h1><span>ملخص التنفيذ والفوترة والتحصيل وإغلاق الطلبات المسددة.</span></div></section><section className="stats"><Stat label="إجمالي الفواتير" value={billed.toLocaleString("ar-SA")} note="ر.س" icon={<ReceiptText/>}/><Stat label="إجمالي التحصيل" value={collected.toLocaleString("ar-SA")} note="ر.س" icon={<WalletCards/>}/><Stat label="الرصيد المستحق" value={Math.max(0,billed-collected).toLocaleString("ar-SA")} note="ر.س" icon={<Clock3/>}/><Stat label="طلبات مغلقة" value={String(requestsData.filter(r=>r.closed_at).length)} note="مغلقة بالكامل" icon={<CheckCircle2/>}/></section><section className="reportColumns"><div className="panel"><h2>الفواتير النهائية</h2>{invoices.length?invoices.map(i=><article className="reportRow" key={String(i.id)}><div><strong>{String(i.invoice_no)}</strong><span>{String(i.customer_name)} — {Number(i.total||0).toLocaleString("ar-SA")} ر.س</span></div><b>{i.status==="paid"?"مدفوعة":i.status==="partially_paid"?"جزئية":"مستحقة"}</b><button onClick={()=>setSelected(i)}>طباعة</button></article>):<div className="emptyState">لا توجد فواتير</div>}</div><div className="panel"><h2>طلبات جاهزة للإغلاق</h2>{requestsData.filter(r=>r.status==="completed"&&!r.closed_at).length?requestsData.filter(r=>r.status==="completed"&&!r.closed_at).map(r=><article className="reportRow" key={String(r.id)}><div><strong>{String(r.request_no)}</strong><span>{String(r.customer_name)} — {String(r.service_type)}</span></div><button onClick={()=>close(String(r.id))}>إغلاق الطلب</button></article>):<div className="emptyState">لا توجد طلبات جاهزة للإغلاق</div>}</div></section>
  <Dialog open={Boolean(selected)} onOpenChange={v=>!v&&setSelected(null)}><DialogContent dir="rtl" className="invoicePrintDialog"><div className="invoicePrintCard"><header><img src="/brand/logo.png" alt="Purity Ritual"/><div><h2>فاتورة ضريبية</h2><strong>{String(selected?.invoice_no||"")}</strong></div></header><section><p><b>العميل:</b> {String(selected?.customer_name||"")}</p><p><b>البيان:</b> {String(selected?.description||"")}</p><p><b>تاريخ الاستحقاق:</b> {String(selected?.due_date||"—")}</p></section><table><tbody><tr><td>المبلغ قبل الضريبة</td><td>{Number(selected?.subtotal||0).toLocaleString("ar-SA")} ر.س</td></tr><tr><td>ضريبة القيمة المضافة</td><td>{(Number(selected?.total||0)-Number(selected?.subtotal||0)).toLocaleString("ar-SA")} ر.س</td></tr><tr><th>الإجمالي</th><th>{Number(selected?.total||0).toLocaleString("ar-SA")} ر.س</th></tr></tbody></table><footer>Purity Ritual — +966 55 533 0406 — ahmedazi911@gmail.com</footer></div><button className="primary printButton" onClick={()=>window.print()}>طباعة الفاتورة</button></DialogContent></Dialog></div>;
}

